using namespace std;

void countingSort(int arr[], int n, int place) {
  int output[n];
  int count[10] = {0};

  for (int i = 0; i < n; i++)
    count[(arr[i] / place) % 10]++;

  for (int i = 1; i < 10; i++)
    count[i] += count[i - 1];

  for (int i = n - 1; i >= 0; i--) {
    output[count[(arr[i] / place) % 10] - 1] = arr[i];
    count[(arr[i] / place) % 10]--;
  }

  for (int i = 0; i < n; i++)
    arr[i] = output[i];
}

